#!/usr/bin/env node

/**
 * Credential Verification Test Script
 * Tests connectivity and validity of credentials in .env.test
 * DO NOT RUN THIS IN PRODUCTION
 */

require('dotenv').config({ path: '.env.test' });
const fs = require('fs');
const { Pool } = require('pg');
const { STSClient, GetCallerIdentityCommand } = require('@aws-sdk/client-sts');
const Stripe = require('stripe');
const Anthropic = require('@anthropic-ai/sdk');

// ANSI color codes
const colors = {
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  reset: '\x1b[0m'
};

function log(msg, color = 'reset') {
  console.log(`${colors[color]}${msg}${colors.reset}`);
}

function maskSecret(secret) {
  if (!secret) return 'NOT_FOUND';
  return secret.substring(0, 8) + '****' + secret.substring(secret.length - 4);
}

async function testDatabaseConnection() {
  log('\n🔍 Testing Database Connection...', 'blue');

  const dbUrl = process.env.DATABASE_URL;
  log(`   Database URL: ${dbUrl ? dbUrl.replace(/:\/\/([^:]+):([^@]+)@/, '://$1:****@') : 'NOT_FOUND'}`, 'yellow');

  if (!dbUrl) {
    log('   ❌ DATABASE_URL not found', 'red');
    return false;
  }

  // Check if it's a canary/test credential
  if (dbUrl.includes('CANARY')) {
    log('   ⚠️  Canary credential detected - skipping actual connection test', 'yellow');
    log('   ℹ️  In production, this would attempt to connect to: ' + dbUrl.replace(/:\/\/([^:]+):([^@]+)@/, '://$1:****@'), 'yellow');
    return null; // null indicates canary/test value
  }

  // Parse the URL to extract components
  try {
    const pool = new Pool({
      connectionString: dbUrl,
      connectionTimeoutMillis: 5000,
      query_timeout: 5000,
      statement_timeout: 5000
    });

    const startTime = Date.now();
    const client = await pool.connect();
    const result = await client.query('SELECT version()');
    const endTime = Date.now();

    log(`   ✅ Database connected successfully`, 'green');
    log(`   📊 Response time: ${endTime - startTime}ms`, 'green');
    log(`   🖥️  PostgreSQL version: ${result.rows[0].version.split(' ')[1]}`, 'green');

    client.release();
    await pool.end();
    return true;
  } catch (error) {
    log(`   ❌ Database connection failed: ${error.message}`, 'red');
    return false;
  }
}

async function testAWSAccessKey() {
  log('\n🔍 Testing AWS Credentials...', 'blue');

  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

  log(`   Access Key ID: ${accessKeyId || 'NOT_FOUND'}`, 'yellow');
  log(`   Secret Key: ${maskSecret(secretAccessKey)}`, 'yellow');

  if (!accessKeyId || !secretAccessKey) {
    log('   ❌ AWS credentials not found', 'red');
    return false;
  }

  // Check if it's a canary/test credential
  if (accessKeyId.includes('CANARY')) {
    log('   ⚠️  Canary credential detected - skipping actual AWS Call', 'yellow');
    log('   ℹ️  In production, this would call GetCallerIdentity', 'yellow');
    return null;
  }

  try {
    const stsClient = new STSClient({
      region: process.env.AWS_REGION || 'us-east-1',
      credentials: {
        accessKeyId,
        secretAccessKey
      }
    });

    const startTime = Date.now();
    const response = await stsClient.send(new GetCallerIdentityCommand({}));
    const endTime = Date.now();

    log(`   ✅ AWS credentials are valid`, 'green');
    log(`   📊 Account ID: ${response.Account}`, 'green');
    log(`   📊 User/Role ARN: ${response.Arn}`, 'green');
    log(`   📊 Response time: ${endTime - startTime}ms`, 'green');

    // Check if this is a test account (optional)
    if (response.Account === '123456789012') {
      log('   ⚠️  Using test account credentials', 'yellow');
    }

    return true;
  } catch (error) {
    log(`   ❌ AWS credentials failed: ${error.message}`, 'red');
    if (error.message.includes('InvalidAccessKeyId')) {
      log('   🔑 The access key ID is invalid (may be deactivated)', 'red');
    }
    return false;
  }
}

async function testAnthropicAPIKey() {
  log('\n🔍 Testing Anthropic API Key...', 'blue');

  const apiKey = process.env.ANTHROPIC_API_KEY;
  log(`   API Key: ${maskSecret(apiKey)}`, 'yellow');

  if (!apiKey) {
    log('   ❌ ANTHROPIC_API_KEY not found', 'red');
    return false;
  }

  // Check if it's a canary/test credential
  if (apiKey.includes('CANARY')) {
    log('   ⚠️  Canary credential detected - skipping actual API call', 'yellow');
    log('   ℹ️  In production, this would call messages.create() with minimal input', 'yellow');
    return null;
  }

  try {
    const anthropic = new Anthropic({
      apiKey,
      timeout: 10000
    });

    const startTime = Date.now();
    // Make a minimal API call to validate the key without consuming many tokens
    const response = await anthropic.messages.create({
      model: 'claude-3-haiku-20240307',
      max_tokens: 10,
      messages: [
        {
          role: 'user',
          content: 'Test message to validate API key'
        }
      ]
    });
    const endTime = Date.now();

    log(`   ✅ Anthropic API key is valid`, 'green');
    log(`   📊 Response time: ${endTime - startTime}ms`, 'green');
    log(`   📊 Model accessed: ${response.model}`, 'green');

    return true;
  } catch (error) {
    if (error.status === 401 || error.status === 403) {
      log(`   ❌ Anthropic API key is invalid or expired: ${error.message}`, 'red');
    } else if (error.status === 429) {
      log(`   ⚠️  Rate limited: ${error.message}`, 'yellow');
      return null; // Key might be valid but rate limited
    } else {
      log(`   ❌ Anthropic API error: ${error.message}`, 'red');
    }
    return false;
  }
}

async function testStripeSecretKey() {
  log('\n🔍 Testing Stripe Secret Key...', 'blue');

  const secretKey = process.env.STRIPE_SECRET_KEY;
  log(`   Secret Key: ${maskSecret(secretKey)}`, 'yellow');

  if (!secretKey) {
    log('   ❌ STRIPE_SECRET_KEY not found', 'red');
    return false;
  }

  // Check if it's a canary/test credential
  if (secretKey.includes('CANARY')) {
    log('   ⚠️  Canary credential detected - skipping actual API call', 'yellow');
    log('   ℹ️  In production, this would retrieve account details', 'yellow');
    return null;
  }

  try {
    const stripe = new Stripe(secretKey, {
      timeout: 20000,
      apiVersion: '2023-10-16'
    });

    const startTime = Date.now();
    // Test with a simple API call that requires valid credentials
    const account = await stripe.accounts.retrieve('me');
    const endTime = Date.now();

    log(`   ✅ Stripe secret key is valid`, 'green');
    log(`   📊 Account: ${account.business_profile?.name || account.email || account.id}`, 'green');
    log(`   📊 Environment: ${account.charges_enabled ? 'Live' : 'Test'}`, 'green');
    log(`   📊 Country: ${account.country?.toUpperCase() || 'Unknown'}`, 'green');
    log(`   📊 Response time: ${endTime - startTime}ms`, 'green');

    return true;
  } catch (error) {
    if (error.statusCode === 401 || error.type === 'StripeAuthenticationError') {
      log(`   ❌ Stripe secret key is invalid: ${error.message}`, 'red');
    } else {
      log(`   ❌ Stripe API error: ${error.message}`, 'red');
    }
    return false;
  }
}

async function testLogfireToken() {
  log('\n🔍 Testing Logfire Token...', 'blue');

  const token = process.env.LOGFIRE_TOKEN;
  log(`   Token: ${maskSecret(token)}`, 'yellow');

  if (!token) {
    log('   ❌ LOGFIRE_TOKEN not found', 'red');
    return false;
  }

  // Check if it's a canary/test credential
  if (token.includes('CANARY')) {
    log('   ⚠️  Canary credential detected - skipping actual API call', 'yellow');
    log('   ℹ️  In production, this would validate the token', 'yellow');
    return null;
  }

  try {
    // Logfire uses a JWT-like token structure
    // We can validate it by attempting to emit a test log event
    const https = require('https');

    const startTime = Date.now();
    const response = await new Promise((resolve, reject) => {
      const req = https.request({
        hostname: 'logfire-api.pydantic.dev', // Assuming this is the endpoint
        port: 443,
        path: '/v1/health',
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        timeout: 5000
      }, (res) => {
        let data = '';
        res.on('data', chunk => data += chunk);
        res.on('end', () => resolve({ statusCode: res.statusCode, data }));
      });

      req.on('error', reject);
      req.on('timeout', () => {
        req.destroy();
        reject(new Error('Request timeout'));
      });

      req.end();
    });

    const endTime = Date.now();

    if (response.statusCode !== 200 && response.statusCode !== 401) {
      throw new Error(`Unexpected status code: ${response.statusCode}`);
    }

    log(`   ✅ Logfire token structure is valid`, 'green');
    log(`   📊 Response time: ${endTime - startTime}ms`, 'green');
    log(`   📊 Status: ${response.statusCode === 200 ? 'Active' : 'Needs validation'}`, 'green');

    return true;
  } catch (error) {
    log(`   ⚠️  Logfire token validation incomplete: ${error.message}`, 'yellow');
    log('   ℹ️  Could not reach Logfire API or token requires full integration test', 'yellow');
    return null; // Not a hard failure
  }
}

async function main() {
  log('========================================', 'blue');
