#!/usr/bin/env node

/**
 * Credential Validation Test Script
 * Tests connectivity to external services using environment variables
 */

require('dotenv').config({ path: '.env.test' });
const crypto = require('crypto');

// Helper to mask sensitive values
function maskSecret(secret) {
  if (!secret) return 'NOT_SET';
  if (secret.length <= 8) return '***';
  return secret.substring(0, 4) + '...' + secret.substring(secret.length - 4);
}

// Test results storage
const results = [];

function logResult(service, variable, status, details, isError = false) {
  results.push({
    service,
    variable,
    status,
    details,
    isError
  });

  const icon = isError ? '❌' : '✅';
  const statusColor = isError ? '\x1b[31m' : '\x1b[32m';
  const resetColor = '\x1b[0m';

  console.log(`${icon} ${service} (${variable})`);
  console.log(`   Status: ${statusColor}${status}${resetColor}`);
  if (details) console.log(`   Details: ${details}`);
  console.log('');
}

async function testDatabaseURL() {
  const url = process.env.DATABASE_URL;

  if (!url) {
    logResult('PostgreSQL', 'DATABASE_URL', 'FAILED', 'Environment variable not set', true);
    return;
  }

  try {
    const { Client } = require('pg');
    const client = new Client({ connectionString: url });

    await client.connect();
    const res = await client.query('SELECT version()');
    await client.end();

    const version = res.rows[0].version.split(' ')[1];
    logResult('PostgreSQL', 'DATABASE_URL', 'SUCCESS', `Connected to PostgreSQL ${version}`);
  } catch (error) {
    logResult('PostgreSQL', 'DATABASE_URL', 'FAILED', error.message, true);
  }
}

async function testRedisURL() {
  const url = process.env.REDIS_URL;

  if (!url) {
    logResult('Redis', 'REDIS_URL', 'SKIPPED', 'Environment variable not set');
    return;
  }

  try {
    const redis = require('redis');
    const client = redis.createClient({ url });

    client.on('error', (err) => {
      throw err;
    });

    await client.connect();
    const pong = await client.ping();
    await client.disconnect();

    logResult('Redis', 'REDIS_URL', 'SUCCESS', `Redis responded: ${pong}`);
  } catch (error) {
    logResult('Redis', 'REDIS_URL', 'FAILED', error.message, true);
  }
}

async function testStripeKey() {
  const key = process.env.STRIPE_SECRET_KEY;

  if (!key) {
    logResult('Stripe', 'STRIPE_SECRET_KEY', 'SKIPPED', 'Environment variable not set');
    return;
  }

  // Basic format validation
  if (!key.startsWith('sk_') && !key.startsWith('rk_')) {
    logResult('Stripe', 'STRIPE_SECRET_KEY', 'WARNING', 'Key doesn\'t start with sk_ or rk_', false);
    return;
  }

  try {
    const stripe = require('stripe')(key);
    const account = await stripe.account.retrieve();

    logResult('Stripe', 'STRIPE_SECRET_KEY', 'SUCCESS', 
      `Connected to Stripe account: ${account.id} (${account.charges_enabled ? 'Live' : 'Test'})`);
  } catch (error) {
    if (error.type === 'StripeAuthenticationError') {
      logResult('Stripe', 'STRIPE_SECRET_KEY', 'FAILED', 'Invalid API key - authentication failed', true);
    } else {
      logResult('Stripe', 'STRIPE_SECRET_KEY', 'WARNING', `May be valid but test failed: ${error.message}`);
    }
  }
}

async function testSendGridKey() {
  const key = process.env.SENDGRID_API_KEY;

  if (!key) {
    logResult('SendGrid', 'SENDGRID_API_KEY', 'SKIPPED', 'Environment variable not set');
    return;
  }

  // Basic format validation
  if (!key.startsWith('SG.')) {
    logResult('SendGrid', 'SENDGRID_API_KEY', 'WARNING', 'Key doesn\'t start with SG.', false);
    return;
  }

  try {
    // Simple API key validation using the Web API
    const https = require('https');

    await new Promise((resolve, reject) => {
      const options = {
        hostname: 'api.sendgrid.com',
        path: '/v3/user/profile',
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${key}`,
          'Content-Type': 'application/json'
        }
      };

      const req = https.request(options, (res) => {
        let data = '';
        res.on('data', (chunk) => data += chunk);
        res.on('end', () => {
          if (res.statusCode === 200) {
            try {
              const profile = JSON.parse(data);
              logResult('SendGrid', 'SENDGRID_API_KEY', 'SUCCESS', 
                `Connected to SendGrid account: ${profile.email}`);
              resolve();
            } catch (e) {
              reject(new Error('Invalid JSON response'));
            }
          } else {
            reject(new Error(`HTTP ${res.statusCode}: ${data}`));
          }
        });
      });

      req.on('error', reject);
      req.end();
    });
  } catch (error) {
    if (error.message.includes('401') || error.message.includes('403')) {
      logResult('SendGrid', 'SENDGRID_API_KEY', 'FAILED', 'Invalid API key - authentication failed', true);
    } else {
      logResult('SendGrid', 'SENDGRID_API_KEY', 'WARNING', `May be valid but test failed: ${error.message}`);
    }
  }
}

async function testGitHubToken() {
  const token = process.env.GITHUB_TOKEN;

  if (!token) {
    logResult('GitHub', 'GITHUB_TOKEN', 'SKIPPED', 'Environment variable not set');
    return;
  }

  // Format validation
  const formats = ['ghp_', 'gho_', 'github_pat_'];
  const isValidFormat = formats.some(prefix => token.startsWith(prefix));

  if (!isValidFormat) {
    logResult('GitHub', 'GITHUB_TOKEN', 'WARNING', 
      'Token format may be outdated or invalid', false);
    return;
  }

  try {
    const https = require('https');

    await new Promise((resolve, reject) => {
      const options = {
        hostname: 'api.github.com',
        path: '/user',
        method: 'GET',
        headers: {
          'Authorization': `token ${token}`,
          'User-Agent': 'Credential-Test-Script',
          'Accept': 'application/vnd.github.v3+json'
        }
      };

      const req = https.request(options, (res) => {
        let data = '';
        res.on('data', (chunk) => data += chunk);
        res.on('end', () => {
          if (res.statusCode === 200) {
            try {
              const user = JSON.parse(data);
              // Check scopes from response headers
              const scopes = res.headers['x-oauth-scopes'] || 'None';
              logResult('GitHub', 'GITHUB_TOKEN', 'SUCCESS', 
                `Connected to GitHub as: ${user.login} (Scopes: ${scopes})`);
              resolve();
            } catch (e) {
              reject(new Error('Invalid JSON response'));
            }
          } else if (res.statusCode === 401) {
            reject(new Error('Invalid token - authentication failed'));
          } else {
            reject(new Error(`HTTP ${res.statusCode}: ${data}`));
          }
        });
      });

      req.on('error', reject);
      req.end();
    });
  } catch (error) {
    if (error.message.includes('authentication failed')) {
      logResult('GitHub', 'GITHUB_TOKEN', 'FAILED', 'Invalid token', true);
    } else {
      logResult('GitHub', 'GITHUB_TOKEN', 'WARNING', `May be valid but test failed: ${error.message}`);
    }
  }
}

async function testAWSCredentials() {
  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!accessKeyId || !secretAccessKey) {
    logResult('AWS', 'AWS_ACCESS_KEY_ID/AWS_SECRET_ACCESS_KEY', 'SKIPPED', 
      'One or both variables not set');
    return;
  }

  // Format validation
  if (!accessKeyId.startsWith('AKIA') && !accessKeyId.startsWith('ASIA')) {
    logResult('AWS', 'AWS_ACCESS_KEY_ID', 'WARNING', 
      'Access key ID doesn\'t start with AKIA or ASIA (may be invalid format)', false);
  }

  try {
    // Use the AWS SDK to test credentials with STS GetCallerIdentity
    const AWS = require('aws-sdk');
    const sts = new AWS.STS({ 
      accessKeyId, 
      secretAccessKey,
      region: process.env.AWS_REGION || 'us-east-1'
    });

    const identity = await sts.getCallerIdentity().promise();
    logResult('AWS', 'AWS Credentials', 'SUCCESS', 
      `Authenticated as: ${identity.Arn}`);
  } catch (error) {
    if (error.code === 'CredentialsError' || error.code === 'InvalidClientTokenId') {
      logResult('AWS', 'AWS Credentials', 'FAILED', 'Invalid AWS credentials', true);
    } else {
      logResult('AWS', 'AWS Credentials', 'WARNING', 
        `May be valid but test failed: ${error.message}`);
    }
  }
}

async function testJwtSecret() {
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    logResult('JWT', 'JWT_SECRET', 'FAILED', 'Environment variable not set', true);
    return;
  }

  // Security validation
  const issues = [];

  if (secret.length < 32) {
    issues.push('Too short (should be at least 32 characters)');
  }

  if (!/[a-z]/.test(secret) || !/[A-Z]/.test(secret) || !/[0-9]/.test(secret)) {
    issues.push('Should contain a mix of uppercase, lowercase, and numbers');
  }

  if (/^(password|secret|jwt|123|abc)/i.test(secret)) {
    issues.push('Too predictable (common pattern)');
  }

  if (issues.length > 0) {
    logResult('JWT', 'JWT_SECRET', 'WARNING', 
      `Weak secret: ${issues.join(', ')}`, false);
  } else {
    logResult('JWT', 'JWT_SECRET', 'SUCCESS', 'Strong secret (length and complexity OK)');
  }
}

async function testSessionSecret() {
  const secret = process.env.SESSION_SECRET;

  if (!secret) {
    logResult('Session', 'SESSION_SECRET', 'FAILED', 'Environment variable not set', true);
    return;
