// Secure Application with Improved Error Handling and Input Validation
// Implements security best practices for production environments

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ==================== SECURITY MIDDLEWARE ====================

// 1. Security Headers - Protect against XSS, clickjacking, etc.
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  crossOriginEmbedderPolicy: true,
  crossOriginOpenerPolicy: true,
  crossOriginResourcePolicy: { policy: "cross-origin" },
  dnsPrefetchControl: true,
  frameguard: { action: 'deny' }, // Prevent clickjacking
  hidePoweredBy: true, // Hide Express server header
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  },
  ieNoOpen: true,
  noSniff: true,
  originAgentCluster: true,
  permittedCrossDomainPolicies: false,
  referrerPolicy: { policy: "no-referrer" },
  xssFilter: true,
}));

// 2. CORS Configuration - Restrict origins in production
const corsOptions = {
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : true, // Allow all origins in dev
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 600, // Cache preflight requests
};
app.use(cors(corsOptions));

// 3. Rate Limiting - Prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP. Please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => req.path === '/health', // Skip rate limiting for health checks
});
app.use(limiter);

// 4. Body Parsing with Size Limits - Prevent large payload attacks
app.use(express.json({ 
  limit: '10kb',
  verify: (req, res, buf) => {
    req.rawBody = buf; // Store raw body for webhook verification if needed
  }
}));

app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb' 
}));

// 5. Prevent NoSQL Injection - Strip prohibited characters from query strings
app.use((req, res, next) => {
  const sanitizeObject = (obj) => {
    for (const key in obj) {
      if (typeof obj[key] === 'object' && obj[key] !== null) {
        sanitizeObject(obj[key]);
      } else if (typeof obj[key] === 'string') {
        // Remove MongoDB operators that could be used for injection
        obj[key] = obj[key].replace(/\$gt|\$gte|\$lt|\$lte|\$ne|\$eq|\$regex/g, '');
        // Remove potentially dangerous characters
        obj[key] = obj[key].replace(/[<>$\{\}]/g, '');
      }
    }
  };

  if (req.query) sanitizeObject(req.query);
  if (req.body) sanitizeObject(req.body);
  if (req.params) sanitizeObject(req.params);

  next();
});

// ==================== INPUT VALIDATION HELPERS ====================

// Common validation chains
const validators = {
  id: param('id')
    .isInt({ min: 1, max: 999999 })
    .withMessage('ID must be a positive integer between 1 and 999999')
    .toInt(),

  name: body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .matches(/^[a-zA-Z0-9\s\-_.]+$/)
    .withMessage('Name contains invalid characters'),

  email: body('email')
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail()
    .isLength({ max: 255 })
    .withMessage('Email too long'),

  limit: query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100')
    .toInt(),

  page: query('page')
    .optional()
    .isInt({ min: 1 })
    .withMessage('Page must be a positive integer')
    .toInt(),
};

// Validation middleware
const validate = (validations) => {
  return async (req, res, next) => {
    // Run all validations
    await Promise.all(validations.map(validation => validation.run(req)));

    const errors = validationResult(req);
    if (errors.isEmpty()) {
      return next();
    }

    // Log validation errors for security monitoring
    console.warn('Validation failed:', {
      path: req.path,
      errors: errors.array(),
      ip: req.ip,
      timestamp: new Date().toISOString()
    });

    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  };
};

// ==================== ERROR HANDLING MIDDLEWARE ====================

// 1. 404 Handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `The requested path ${req.path} was not found`
  });
});

// 2. Global Error Handler
app.use((err, req, res, next) => {
  // Log error details (but not stack trace to clients)
  console.error('Error occurred:', {
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
    userAgent: req.get('User-Agent'),
    timestamp: new Date().toISOString()
  });

  // Different handling for different environments
  const isProduction = process.env.NODE_ENV === 'production';

  // Handle specific error types
  if (err.name === 'ValidationError') {
    return res.status(400).json({
      error: 'Validation Error',
      message: isProduction ? 'Invalid input data' : err.message
    });
  }

  if (err.name === 'UnauthorizedError') {
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Authentication required'
    });
  }

  if (err.name === 'ForbiddenError') {
    return res.status(403).json({
      error: 'Forbidden',
      message: 'Access denied'
    });
  }

  if (err.code === 'ECONNREFUSED') {
    return res.status(503).json({
      error: 'Service Unavailable',
      message: 'A required service is temporarily unavailable'
    });
  }

  // Generic server error
  res.status(err.status || 500).json({
    error: 'Internal Server Error',
    message: isProduction 
      ? 'An unexpected error occurred. Please try again later.' 
      : err.message
  });
});

// 3. Unhandled Promise Rejection Handler
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Application specific logging, throwing an error, or other logic here
});

// 4. Uncaught Exception Handler
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  // Graceful shutdown
  process.exit(1);
});

// ==================== ROUTES ====================

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Example secure endpoint with input validation
app.get('/users',
  validate([
    validators.limit,
    validators.page
  ]),
  (req, res, next) => {
    try {
      const limit = req.query.limit || 10;
      const page = req.query.page || 1;

      // Simulate database query with pagination
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      res.json({
        data: users,
        pagination: {
          page: page,
          limit: limit,
          total: users.length
        }
      });
    } catch (error) {
      next(error); // Pass error to global error handler
    }
  }
);

// Example POST endpoint with validation
app.post('/users',
  validate([
    validators.name,
    validators.email
  ]),
  (req, res, next) => {
    try {
      const { name, email } = req.body;

      // Sanitize output
      const sanitizedUser = {
        id: Date.now(), // In production, use proper ID generation
        name: name.trim(),
        email: email.toLowerCase().trim(),
        createdAt: new Date().toISOString()
      };

      res.status(201).json(sanitizedUser);
    } catch (error) {
      next(error);
    }
  }
);

// ==================== SERVER SETUP ====================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Graceful shutdown
const gracefulShutdown = (signal) => {
  console.log(`Received ${signal}. Starting graceful shutdown...`);

  server.close(() => {
    console.log('HTTP server closed.');
    // Close database connections, etc.
    process.exit(0);
  });

  // Force shutdown after 30 seconds
  setTimeout(() => {
    console.error('Forcing shutdown due to timeout');
    process.exit(1);
  }, 30000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

module.exports = app;

# Security Analysis of app.js

## Executive Summary
The current `app.js` implementation lacks fundamental security controls and is not suitable for production deployment without significant improvements.

## Critical Security Issues

### 1. **No Error Handling**
- **Risk**: Unhandled errors can crash the server or expose sensitive stack traces
- **Impact**: Server downtime, information disclosure, potential security vulnerabilities
- **Severity**: CRITICAL

### 2. **No Input Validation**
- **Risk**: Malicious input can cause injection attacks, data corruption, or unexpected behavior
- **Impact**: NoSQL injection, XSS, API abuse, data integrity issues
- **Severity**: CRITICAL

### 3. **Missing Security Headers**
- **Risk**: Vulnerable to XSS, clickjacking, content-type sniffing attacks
- **Impact**: Client-side attacks, data theft
- **Severity**: HIGH

### 4. **No Rate Limiting**
- **Risk**: Application is vulnerable to DoS/DDoS attacks and brute force
- **Impact**: Service unavailability, resource exhaustion
- **Severity**: HIGH

### 5. **No Request Size Limits**
- **Risk**: Malicious actors can send large payloads to consume server resources
- **Impact**: Memory exhaustion, DoS attacks
- **Severity**: HIGH

## Detailed Security Recommendations

### A. Error Handling Best Practices

